class Solution {
    int settle(int start, vector<long long>& debt) {
        while (start < static_cast<int>(debt.size()) && debt[start] == 0) {
            ++start;
        }
        if (start == static_cast<int>(debt.size())) {
            return 0;
        }
        int best = INT_MAX;
        for (int j = start + 1; j < static_cast<int>(debt.size()); ++j) {
            if (debt[start] * debt[j] >= 0) {
                continue;
            }
            long long old = debt[j];
            debt[j] += debt[start];
            best = min(best, 1 + settle(start + 1, debt));
            debt[j] = old;
            if (old + debt[start] == 0) {
                break;
            }
        }
        return best;
    }

public:
    int minTransfers(vector<vector<int>>& transactions) {
        unordered_map<int, long long> balance;
        for (const auto& t : transactions) {
            balance[t[0]] -= t[2];
            balance[t[1]] += t[2];
        }
        vector<long long> debt;
        for (const auto& entry : balance) {
            if (entry.second != 0) {
                debt.push_back(entry.second);
            }
        }
        return settle(0, debt);
    }
};
